/*
 * Design:
 * -------
 * Previous versions of this selector focused on spreading traffic evenly
 * across workers (e.g., via per-packet randomness). That flattens per‑worker
 * utilization but still mixes short GETs (~10 µs) and long SCANs (~2 ms) on
 * every UDP receive queue. Even with balanced CPU, rare SCANs create
 * head-of-line blocking for many queued GETs on a given worker, which shows
 * up as high end-to-end p99 latency at high load.
 *
 * Goals:
 *   - Minimize the time GETs spend queued behind SCANs.
 *   - Keep all workers usefully busy without new maps or user-space config.
 *   - Stay verifier-friendly: O(1) per packet, no loops, minimal state.
 *
 * Approach: static GET / SCAN lane partitioning.
 * ----------------------------------------------
 * We use the existing pebble_agent_state map (Active workers) and treat the
 * reuseport sockarray indices as two static "lanes":
 *
 *   - SCAN lane:   index 0 (one worker dedicated to SCANs when Active > 1).
 *   - GET lane:    indices [1, Active-1] (all remaining workers).
 *
 * When there is only a single worker (Active == 1), the lanes collapse and
 * we simply select slot 0.
 *
 * For each packet:
 *   1. Safely parse the incoming IPv4/UDP headers from sk_reuseport_md::data
 *      and locate the UDP payload.
 *   2. Inspect the first few payload bytes to classify the request:
 *        - "SCAN " → SCAN request.
 *        - Everything else (including "GET ...") → treated as GET/other.
 *   3. Choose a lane:
 *        - SCANs → SCAN lane (slot range [0, 0] when Active > 1).
 *        - GET/other → GET lane (slot range [1, Active-1] when Active > 1).
 *   4. Within the chosen lane, pick a worker index using
 *      bpf_get_prandom_u32() % lane_size.
 *   5. Call bpf_sk_select_reuseport once with that slot.
 *
 * This ensures that long SCAN requests are funneled into a small, fixed
 * subset of workers and do not share UDP queues with GETs. GETs are thus
 * processed on workers that rarely, if ever, run SCANs, substantially
 * reducing their queueing delay and improving overall p99 latency.
 *
 * The program remains:
 *   - Stateless per packet (no per-flow state, no counters).
 *   - O(1) in work and memory.
 *   - Within verifier limits (no loops, all pointer accesses bounds-checked).
 */

struct agent_state {
    __u32 active;
    __u32 pad;
};

struct {
    __uint(type, BPF_MAP_TYPE_ARRAY);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, struct agent_state);
    __uint(pinning, LIBBPF_PIN_BY_NAME);
} pebble_agent_state SEC(".maps");

